import argparse,json,os;from sentence_transformers import SentenceTransformer;parser=argparse.ArgumentParser(description='Offline multilingual sentence embeddings for MicrocosmLab research');parser.add_argument('--corpus',default='artifacts/recommendation-corpus.json');parser.add_argument('--output',default='artifacts/sentence-embeddings.json');parser.add_argument('--model',default='sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2');parser.add_argument('--batch-size',type=int,default=16);args=parser.parse_args();corpus=json.load(open(args.corpus,encoding='utf-8'));model=SentenceTransformer(args.model,trust_remote_code=False);vectors=model.encode([item['text'] for item in corpus],batch_size=args.batch_size,normalize_embeddings=True,show_progress_bar=True);os.makedirs(os.path.dirname(args.output) or '.',exist_ok=True);payload={'model':args.model,'dimension':int(vectors.shape[1]),'count':len(corpus),'vectors':{item['id']:[round(float(v),5) for v in vector] for item,vector in zip(corpus,vectors)}};json.dump(payload,open(args.output,'w',encoding='utf-8'),ensure_ascii=False,separators=(',',':'));print('Generated actual model embeddings:',payload['model'],payload['count'],payload['dimension']);
